import json
from pathlib import Path
p=Path('Tools/SettingsCatalog.json');d=json.loads(p.read_text());entries=[
('medicationVitalChecksEnabled','Medication','Medication vital-sign safeguards',1,0,1,1,'Reject medication when the current server vital signs fail its safety checks. The checks are repeated during treatment; disabling this permits risky administration but does not remove physiological effects.'),
('morphineMinimumHeartRate','Medication','Morphine minimum pulse (bpm)',50,20,80,1,'Lowest pulse accepted for morphine administration. A slower pulse blocks another dose so the medic can assess circulation and respiratory depression first.'),
('morphineMinimumSystolicPressure','Medication','Morphine minimum systolic pressure',90,50,120,1,'Minimum systolic pressure for morphine. Below this value the server retains the kit and rejects treatment because further opioid-related pressure reduction could worsen perfusion.'),
('morphineMinimumRespiratoryRate','Medication','Morphine minimum breathing rate',10,4,16,1,'Minimum spontaneous breaths per minute for morphine. Slow breathing blocks additional opioid administration; ventilation and reversal remain separate treatments.'),
('morphineMinimumOxygenFraction','Medication','Morphine minimum oxygen saturation',.9,.5,.98,.01,'Minimum oxygen saturation for another morphine dose, expressed as a fraction. The default 0.90 corresponds to 90 percent; this is a configurable game safeguard.'),
('epinephrineMaximumHeartRate','Medication','Epinephrine maximum pulse (bpm)',180,100,240,1,'Reject epinephrine in a patient with a pulse at or above this rate. This does not prohibit indicated resuscitation medication merely because CPR is being performed.'),
('epinephrineMaximumSystolicPressure','Medication','Epinephrine maximum systolic pressure',180,120,240,1,'Reject epinephrine in a patient with spontaneous circulation at or above this pressure. Arrest has a separate context and still requires CPR and correction of reversible causes.'),
('epinephrineWithPulseEnabled','Medication','Allow epinephrine with a pulse',1,0,1,1,'Allow the simplified game injector in patients who still have a pulse, subject to the pulse and pressure limits. Disable this for an arrest-only injector policy; it is not a real drug dosing protocol.'),
('naloxoneRequiresOpioid','Medication','Naloxone requires active opioid',1,0,1,1,'Require an active morphine dose before administering naloxone. Reversal affects opioid-related effects only and cannot repair trauma, replenish blood or resolve an obstructed airway.'),
('fluidSafetyChecksEnabled','Medication','Fluid vital-sign safeguards',1,0,1,1,'Check current systolic pressure and actual native blood deficit before and throughout fluid administration. Unsafe or unnecessary infusions are rejected without deliberately causing an artificial arrest.'),
('fluidMaximumSystolicPressure','Medication','Fluid stop systolic pressure',140,90,200,1,'Stop or reject the simplified fluid procedure at this systolic pressure. This limits unnecessary resuscitation; pressure alone is not simulated as an instant cardiac arrest trigger.'),
('fluidMinimumDeficitMl','Medication','Minimum fluid deficit (ml)',50,0,500,10,'Minimum missing native blood reserve before an infusion is permitted. Delivered volume remains capped at the actual deficit, so a full patient cannot receive extra reserve.'),
('adequateRespiratoryRate','Airway and breathing','Minimum adequate ventilation rate',8,4,16,1,'Spontaneous breathing below this rate progressively reduces the oxygen target. An ordinary modest opioid-related slowdown does not automatically produce profound hypoxia; BVM can support ventilation.'),
('compensatoryHeartRateBoost','Circulation','Blood-loss compensation pulse boost',80,0,150,1,'Maximum pulse increase driven by falling blood reserve before decompensation. Blood loss, pain and stimulants contribute separately; late severe shock can then slow the heart.'),
('painHeartRateBoost','Pain','Maximum pain pulse increase',15,0,40,1,'Maximum additional beats per minute from untreated perceived pain. Analgesia reduces this contribution through the same pain model used for aiming effects.'),
('shockDecompensationBloodFraction','Circulation','Late shock decompensation fraction',.35,.15,.5,.01,'Below this fraction of normal blood reserve, compensatory heart rate starts to fail. This links late bradycardia to severe shock rather than making every slow pulse fatal.'),
('minimumEfficientHeartRate','Circulation','Lower efficient pumping rate',50,20,80,1,'Below this pulse, the model progressively reduces pumping efficiency and pressure. It is a game abstraction of inadequate cardiac output, not a universal clinical cutoff.'),
('maximumEfficientHeartRate','Circulation','Upper efficient pumping rate',180,100,240,1,'Above this pulse, progressively reduced filling lowers pumping efficiency. High pulse becomes dangerous through perfusion and pressure, rather than an arbitrary immediate kill.'),
('criticalBradycardiaRate','Resuscitation','Critical slow pulse threshold',25,10,40,1,'A pulse at or below this threshold contributes to arrest only alongside poor pressure for the configured exposure time. A healthy low resting pulse alone does not trigger arrest.'),
('criticalTachycardiaRate','Resuscitation','Critical fast pulse threshold',220,180,300,1,'A pulse at or above this threshold contributes to arrest only with poor pressure sustained for the configured exposure time. Resulting pulseless tachycardia is assessed by the AED rhythm rules.'),
('criticalSystolicPressure','Resuscitation','Critical perfusion pressure',45,20,70,1,'Sustained systolic pressure at or below this value can lead to nonshockable arrest, including unresolved tension or severe drug-related compromise. Duration is controlled separately.'),
('criticalRatePressureCeiling','Resuscitation','Rate instability pressure ceiling',90,70,120,1,'Rate-extreme arrest requires pressure below this value as well as the slow or fast pulse threshold. This distinguishes instability from a numerical heart-rate alarm alone.'),
('criticalVitalExposureSeconds','Resuscitation','Unstable vital exposure time (seconds)',15,1,120,1,'How long critical pressure or a compromised extreme pulse must persist before arrest. Correcting the cause resets this timer; a brief transient does not automatically cause arrest.'),
('txaInternalBleedReduction','Medication','TXA internal clot support fraction',.2,0,.5,.01,'Maximum reduction in ongoing internal blood loss at full TXA effect. TXA does not repair the source, remove a projectile, drain collected blood or replace external bleeding control.')]
for key,group,label,default,low,high,step,description in entries:
 if not any(x['key']==key for x in d):d.append(dict(key=key,group=group,label=label,default=default,min=low,max=high,step=step,toggle=low==0 and high==1 and step==1,description=description))
