next(x for x in d if x['key']=='equipmentVisualRangeMetres')['description']='Maximum viewer distance for applied equipment models. Increase it to see details farther away; lower it to reduce cosmetic work in busy scenes.'
p.write_text(json.dumps(d,indent=2)+'\n');print('Settings',len(d))
p=Path('Scripts/Game/BCM_Medical/BCMM_Settings.c');s=p.read_text().replace('Schema > 20','Schema > 21').replace('  if (Schema == 20 && Keys.Count() != settings.Count()) return false;','  if (Schema == 20 && Keys.Count() != 144) return false;\n  if (Schema == 20) { for(int twentieth=0;twentieth<144;twentieth++) if(!Keys.Contains(settings.Definition(twentieth).Key)) return false; }\n  if (Schema == 21 && Keys.Count() != settings.Count()) return false;').replace('document.Schema = 20','document.Schema = 21');p.write_text(s)